create table if not exists public.ls_connections (sender uuid references auth.users(id) on delete cascade, recipient uuid references auth.users(id) on delete cascade, accepted boolean not null default false, primary key(sender,recipient), check(sender<>recipient));
create table if not exists public.ls_messages (id bigint generated always as identity primary key, sender uuid references auth.users(id) on delete cascade, recipient uuid references auth.users(id) on delete cascade, body text not null, material jsonb, created_at timestamptz default now());
alter table public.ls_connections enable row level security;
alter table public.ls_messages enable row level security;
revoke all on public.ls_connections,public.ls_messages from anon,authenticated;
create or replace function public.ls_request(peer uuid) returns void language sql security definer set search_path='' as $$ insert into public.ls_connections(sender,recipient) values(auth.uid(),peer) on conflict do nothing $$;
create or replace function public.ls_accept(peer uuid) returns void language sql security definer set search_path='' as $$ update public.ls_connections set accepted=true where sender=peer and recipient=auth.uid() $$;
create or replace function public.ls_friends() returns table(peer uuid,accepted boolean,incoming boolean) language sql security definer set search_path='' as $$ select case when c.sender=auth.uid() then c.recipient else c.sender end,c.accepted,c.recipient=auth.uid() from public.ls_connections c where auth.uid() in(c.sender,c.recipient) $$;
create or replace function public.ls_chat(peer uuid) returns table(sender uuid,body text,material jsonb) language sql security definer set search_path='' as $$ select m.sender,m.body,m.material from public.ls_messages m where ((m.sender=auth.uid() and m.recipient=peer) or (m.recipient=auth.uid() and m.sender=peer)) order by m.id $$;
create or replace function public.ls_send(peer uuid,body text,material jsonb) returns void language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.ls_connections c where c.accepted and ((c.sender=auth.uid() and c.recipient=peer) or(c.recipient=auth.uid() and c.sender=peer))) then raise exception 'Keine bestätigte Freundschaft'; end if; if length(body)>10000 or pg_column_size(material)>4000000 then raise exception 'Nachricht zu groß'; end if; insert into public.ls_messages(sender,recipient,body,material) values(auth.uid(),peer,body,material); end $$;
revoke execute on function public.ls_request(uuid),public.ls_accept(uuid),public.ls_friends(),public.ls_chat(uuid),public.ls_send(uuid,text,jsonb) from public,anon;
grant execute on function public.ls_request(uuid),public.ls_accept(uuid),public.ls_friends(),public.ls_chat(uuid),public.ls_send(uuid,text,jsonb) to authenticated;
